package io.github.diodeme.ji.remote;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.GeneralSecurityException;
import java.security.MessageDigest;
import java.security.PublicKey;
import java.security.Signature;
import java.util.Base64;
import java.util.HexFormat;

/** Verifies a private bundle hash and Ed25519-signed manifest before any SSH transfer. */
public final class BundleVerifier {
    public void verify(BundleManifest manifest, Path archive, PublicKey signingKey) {
        try {
            String actual = HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256")
                    .digest(Files.readAllBytes(archive)));
            if (!MessageDigest.isEqual(actual.getBytes(StandardCharsets.US_ASCII),
                    manifest.archiveSha256().toLowerCase(java.util.Locale.ROOT)
                            .getBytes(StandardCharsets.US_ASCII))) {
                throw new IllegalArgumentException("bundle archive hash mismatch");
            }
            Signature verifier = Signature.getInstance("Ed25519");
            verifier.initVerify(signingKey);
            verifier.update(signedPayload(manifest));
            if (!verifier.verify(Base64.getDecoder().decode(manifest.signature()))) {
                throw new IllegalArgumentException("bundle manifest signature is invalid");
            }
        } catch (IOException exception) {
            throw new IllegalStateException("cannot read Host bundle", exception);
        } catch (GeneralSecurityException | IllegalArgumentException exception) {
            throw new IllegalArgumentException("Host bundle verification failed", exception);
        }
    }

    public static byte[] signedPayload(BundleManifest manifest) {
        return String.join("\n", "ji-host-bundle-v1", manifest.version(), manifest.os(),
                manifest.architecture(), manifest.archiveSha256(), manifest.signatureAlgorithm())
                .getBytes(StandardCharsets.UTF_8);
    }
}
